Import ListNotations. Import AX2. Import AX2B. Import AX2S.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

Import PSMC.
Module PSIU.
Abbreviation RSEGS := PML.RSEGS.
Abbreviation mem := (word -> option byte).
Abbreviation uv := PB.uv.
Abbreviation SSCR := PML.STRTOD_SCR_V.
Abbreviation WDX := PMES.WD_SCR_X.
Abbreviation eghost := PMES.eghost.

(* [comment removed for export] *)
Definition box (X : Prop) : Prop := X.
Definition boxed {X : Prop} (x : X) : box X := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$X;Rw$x;R#1#1").

(* [comment removed for export] *)
Definition seg_of (ps : PML.pstate) : Z := fst (PSA.wincells (PML.ps_win ps)).
Definition wend_of (ps : PML.pstate) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$ps;R+0!3'1+2+2!1'3!1'4#1").

(* [comment removed for export] *)
Definition KEY3 : list Z := [PML.ST_EXPECT_MEMBER_NAME_OR_END; PML.ST_EXPECT_MEMBER_NAME; PML.ST_EXPECT_COLON].
Definition KEYS : list Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3,5+2'6'7").
Definition keyp (st : Z) (stack : list Z) (lvl : Z) (bm : bool) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S00$st;R+2$stack;R!1+8+2$lvl;R+2$bm;R+9%~R!3+:+9#1,;%~R!2+<!3'=+2#5'7!2+>+2$x;R+2!2+?!3'=+2#1#5!3'=+2#1'@!2'A!1,B,C#4").
Definition key_inv (ps1 : PML.pstate) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$ps1;R+0!4'D!1'E#1!1'F#1!1'G#1!1'H#1").
Definition xsync (ps1 : PML.pstate) (eg1 : eghost) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$ps1;R+0$eg1;R+I!2+?!3+:+2!1'J!1'K#1!1'G#2!1'L#2").
Lemma keyp_false : forall st stack lvl, keyp st stack lvl false.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$st;R+2$stack;R!1+8+2$lvl;R+2vd$H;R!3+:+9,M,;&H0;R!6'N+9,M$e;R+9-9RN$b;R+9w#12+O+P,Q,;#1+O!2'R%~R!2+<!3'=+2#5'7!2+>+2$x;R+2!2+?!3'=+2#1#5!3'=+2#1'@!2'A!1,B,C#4#1!4'D#3#2#1,M").
Qed.
Lemma keyp_pos : forall st stack lvl bm, 1 <= lvl -> keyp st stack lvl bm.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$st;R+2$stack;R!1+8+2$lvl;R+2$bm;R+9$H;R!2'A!1,B,C#2vd$_H;R!3+:+9#2,;$_H0;R!2+<!3'=+2#6'7!2+>+2$x;R+2!2+?!3'=+2#1#6!3'=+2#1'@#3!4'D#5#4#3#2").
Qed.
(* [comment removed for export] *)
