(* [comment removed for export] *)
Record inst {SCFG_P : ScfgP} : Type := Inst {
  iL : heap_layout; iHI : heap_iface;
  iHIok : heap_iface_ok iL SCFG iHI;
  iLAY : PmLayout.pm0_layout iL;
  iLBo : list (Z * Z); icr : credit; isp : Z; ir : Z; iP : Z; iV : Z; iE : Z; iS2 : Z; iB : Z; ikx : Z; ibx : Z; ig : PML.ls_state; ips : PML.pstate; ieg : eghost;      (* [comment removed for export] *)
  ifx : FPState; iR : bvmap 5 word; iM : mem; imodel : Model; iK : ShapeAlg.TSet;
  iHH : hi_heap iHI (PML.ps_blocks ips ++ (iLBo ++ PMES.g_lbv ieg)) icr iM (m_vmmaps imodel);      (* [comment removed for export] *)
  iHmo : PML.model_ok imodel;
  iHKnil : iK [];
  iHfp : PML.fp_ok ifx;
  iHentry : PML.entry iL iR iM isp ir (PMX.PSOMEX_SCR SSCR WDX);
  iHa0 : PML.a0 iR iP; iHa1 : PML.a1 iR iV; iHa2 : PML.a2 iR iE;
  iHmore : PML.ps_more ips = true;      (* [comment removed for export] *)
  iHPA : PML.parser_at iM iP ips;
  iHWF : PML.wf_ps ips;
  iHWIN : PML.win_ok iM iLBo ips;
  iHBB : PML.buf_bound ips iB;
  iHVIS : PML.vis_at iM iV;
  iHEC : PML.ec_at iM iE 0;
  iHLS : PML.ls_ok ig iM;
  iHG : ig <> PML.LS0;
  iHkx : 0 <= ikx;      (* [comment removed for export] *)
  iHPC : PML.pcredit_x iL icr ips (ikx + PMX.kenc iL ieg) ibx; ibxu : Z; iHbxu : ibx = ibxu + PMES.benc iL ieg; iHbxu0 : 0 <= ibxu;
  iHINV : PMES.enc_inv iM iV iS2 ieg; iHLIT : PML.lits_ok iM; iHSYNC : PMX.enc_sync ips ieg;      (* [comment removed for export] *)
  iXS : forall ps1 eg1, PMX.enc_sync ps1 eg1 -> xsync ps1 eg1; iSX : forall ps1 eg1, xsync ps1 eg1 -> PMX.enc_sync ps1 eg1;      (* [comment removed for export] *)
  iOBJS : PMX.objs_x iL isp iP iV iE iS2;      (* [comment removed for export] *)
  (* [comment removed for export] *)
  iline0 : Z; ipos0 : Z; iwinb : list Z;
  iHline0 : PML.u64 iM (iP + 160) iline0; iHlr : 0 <= iline0 < 2 ^ 64;
  iHpos0 : PML.u64 iM (iP + 168) ipos0; iHpr : 0 <= ipos0 < 2 ^ 64;
  itag0 : Z; iHtag0 : PML.u8 iM (iP + 220) itag0; iHtr : 0 <= itag0 < 256;      (* [comment removed for export] *)
  iHwinb : L5.bytes_at RSEGS iM (seg_of ips) iwinb /\ Z.of_nat (length iwinb) = wend_of ips - seg_of ips;
  (* [comment removed for export] *)
  iHwrng : Forall (fun b => 0 <= b <= 255) iwinb; ix : list Z; ic0 : PMR.ctrl; iHRM : PMR.rm_match ic0 iM iP ips;
  iHROOM : PMW.wroomrU PMR.the_rm ieg (PMW.rm_step PMR.the_rm PMW.FParseSome ic0 (PMW.inp_win ips iwinb ix));
  (* [comment removed for export] *)
  iHcont : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LB' : list (Z * Z)) (cr' : credit) (LBk : list (Z * Z)) (W : list L5.range),
   PML.fp_ok fx' ->
   (exists (ps' : PML.pstate) (code : Z) (g' : PML.ls_state) (eg' : eghost),
      PML.parser_at M' iP ps' /\ PML.wf_ps ps' /\ PML.win_ok M' iLBo ps' /\ PML.buf_bound ps' iB /\ PML.ec_at M' iE code /\
      (code <> 0 -> PML.ps_more ps' = false) /\ PML.ls_ok g' M' /\ (g' = ig \/ g' = PML.LS2 /\ code <> 0) /\
      PMES.enc_inv M' iV iS2 eg' /\ PML.lits_ok M' /\ (code = 0 -> PMX.enc_sync ps' eg') /\
      LB' = PML.ps_blocks ps' ++ iLBo ++ PMES.g_lbv eg' /\ LBk = iLBo /\ W = PMX.W_parx iP iV iE iS2 /\ PML.pcredit_x iL cr' ps' (ikx + PMX.kenc iL eg') (ibxu + PMES.benc iL eg') /\
      ((code <> 0 \/ PML.ps_more ps' = false \/ PMS.win_exhausted ps') /\
       (PML.ps_st ips = PML.ST_ACCEPT -> code = 0 /\ PML.ps_more ps' = false /\ PML.ps_done ps' = true) /\
       (PMS.win_exhausted ips -> code = 0 -> PML.ps_more ps' = true -> In (PML.ps_st ips) [PML.ST_NUMBER; PML.ST_CR] /\ ~ In (PML.ps_st ps') [PML.ST_NUMBER; PML.ST_CR]) /\
       (code = 0 -> PML.ws_ok ps')) /\
      (* [comment removed for export] *)
      (let rr := PMW.rm_step PMR.the_rm PMW.FParseSome ic0 (PMW.inp_win ips iwinb ix) in
       code = PMW.r_code rr /\ PMES.g_es eg' = PMW.es_run (PMES.g_es ieg) (PMW.r_evs rr) /\
       (exists pay, 0 <= pay <= PMW.r_allow rr /\ PMES.g_len eg' = PMES.g_len ieg + PMW.ind_run (PMES.g_es ieg) (PMW.r_evs rr) + pay) /\
       (code = 0 -> PMW.rm_match PMR.the_rm (PMW.r_ctrl rr) M' iP ps' /\ PMW.r_used rr = PML.winlen ips - PML.winlen ps' /\ PMW.win_bytes M' ps' (PMW.w_after PMR.the_rm rr iwinb)))) ->
   regs_preserved iR R' -> L5C.hpres iL LBk isp (PMX.PSOMEX_SCR SSCR WDX) W iM M' -> model_but_vm imodel model' -> hi_heap iHI LB' cr' M' (m_vmmaps model') ->
   srealizes RSEGS SCFG (@PML.cfg fx' R' ir M' model') iK
}.

(* [comment removed for export] *)
Definition RANK (ps : PML.pstate) : Z :=
