  pose proof OBJRX as HX. pose proof SPF as HS. pose proof WIN as (W0 & W1 & W2 & W3 & W4). try unfold wlen in *.
  destruct W4 as [[Ws Ww]|(ch & Win & Wch & Wwe & Wbr)].
  all: unfold block_range in *.
  all: repeat match goal with H : _ /\ _ |- _ => destruct H end.
  all: unfold know_ok, SPKX.xtra, SPKX.wxtra, PSK.kdisj, SPKX.S2V, SPKX.ENC_SIZE.
  all: cbn [app PSK.c_scr CONSTS X0 PSK.x_p PSK.x_k PSK.x_sb PSK.x_scap].
  all: repeat apply Forall_cons; try apply Forall_nil.
  all: try first [ eapply CL5.krange_intro; [lin_eval; rw_atoms; reflexivity | lia | lia]
                 | apply AxSymRun3.kalign_intro; [lia | cbn [edenot]; rewrite HU52; first [assumption | lia]]
                 | (eapply CL5.kdisj_intro; [ev_start | ev_len | ev_start | ev_len | ];
                    first [ lia | match goal with H : PML.apart _ _ _ _ |- _ => solve [unfold PML.apart in H; lia] end ]) ].
Qed.

