Definition ps_of (pv : PB4.pvals2) (pe ce : expr) (E1 : env) (bm bd : bool) (stack buf : list Z) : PML.pstate :=
  PML.PS (uv E1 (PB4.pv_st pv)) (uv E1 (PB4.pv_sst pv)) (uv E1 (PB4.pv_nst pv)) bm bd (uv E1 (PB4.pv_level pv)) stack
         (uv E1 (PB4.pv_sb pv)) (uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv)) (uv E1 ce) (uv E1 pe) buf
         (PB4.win_of (uv E1 (PB4.pv_wptr pv)) (uv E1 (PB4.pv_wend pv))).
Local Abbreviation cutn := PSM2.cutn.
Local Abbreviation vw := PSM2.vw.
Local Abbreviation in_loop := PSM2.in_loop.  Local Abbreviation under0 := PSM2.under0.  Local Abbreviation reent_pc := PSM2.reent_pc.  Local Abbreviation pushed_of := PSM2.pushed_of.
(* [comment removed for export] *)
Definition contents (pv : PB4.pvals2) (pe ce : expr) (E1 : env) (M1 : mem) (bm bd : bool) (stack buf : list Z) : Prop :=
  L5.bytes_at RSEGS M1 (uv E1 (PB4.pv_sb pv)) stack /\ uv E1 (PB4.pv_send pv) = uv E1 (PB4.pv_sb pv) + Z.of_nat (length stack) /\
  Z.of_nat (length stack) <= uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv) /\ uv E1 (PB4.pv_wend pv) = wend /\ seg <= uv E1 (PB4.pv_wptr pv) <= wend /\
  Z.of_nat (length buf) = uv E1 (PB4.pv_size pv) /\ Z.of_nat (length buf) < uv E1 ce /\ (uv E1 (PB4.pv_st pv) = PML.ST_NUMBER -> L5.bytes_at RSEGS M1 (uv E1 pe) buf) /\
  uv E1 (PB4.pv_more pv) = PML.b2z bm /\ uv E1 (PB4.pv_done pv) = PML.b2z bd /\
  keyp (uv E1 (PB4.pv_st pv)) stack (uv E1 (PB4.pv_level pv)) bm.      (* [comment removed for export] *)


(* [comment removed for export] *)
(* [comment removed for export] *)
Definition w0 : list Z := iwinb I.
Definition c0 : PMR.ctrl := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!2'hB/SCFG_P;/I;").
(* [comment removed for export] *)
Definition SYNC (evs : list PMW.evk) (al : Z) : Prop :=
  PMES.g_es eg = PMW.es_run (PMES.g_es eg0) evs /\ exists pay, 0 <= pay <= al /\ PMES.g_len eg = PMES.g_len eg0 + PMW.ind_run (PMES.g_es eg0) evs + pay.
(* [comment removed for export] *)
Definition rem (E1 : env) (wp : expr) (off : Z) : list Z := skipn (Z.to_nat (uv E1 wp - seg + off)) w0.
(* [comment removed for export] *)
Definition lpos (ps2 : PML.pstate) : Z := fst (PSA.wincells (PML.ps_win ps2)).
(* [comment removed for export] *)
(* [comment removed for export] *)
Definition PTOFF (i : nat) : Z := match nth i PSCW.RACT None with Some PMR.AComma => 1 | _ => 0 end.
Definition PTW (i : nat) (ps2 : PML.pstate) (code : Z) (M1 : mem) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S60|30;!1+8'hC!3+:+2#5,^O!1'hN#2!1'hR#8!1'hS!1'hN#3$i;R+c8$ps2;R+0$code;R+2$M1;R%~R!1+`G!1,`H|600;!1+a9!1+`G!1,`H0!2+>1$evs;R1!2+>+2$al;R+2!2+>+hD$q;R+hD!2+?!3+:+2#5!1'hE#1!2+?!2'hF!3'^0'hC#3!1'hG#1!2'_Y#2!1'hH#1!2+?%~R!1'Z2!3+:+hD!2'hI'hJ'hK!3'hL#4#3#2%~R2!2+?!4'hM3#5!2'a1/SCFG_P;/I;#7!2+?!6'hO'hJ'hK3!3'hP+2!1'c<!2'_Y!2'`4!1'hQ#7'`64'hK!3'^0'hC#4!1'hG#2!2'_Y#3!1'hH#2%~R!3+:+24!1,B,C!2+?!1'Z!3+:+25'^Y!1'Z!3+:+25'_9").      (* [comment removed for export] *)
(* [comment removed for export] *)
Definition WERR (code : Z) : Prop :=
  exists evs al q, PMR.parse_some c0 w0 = PMRF.pre evs al q /\ PMR.q_code q = code /\ SYNC (evs ++ PMR.q_evs q) (al + PMR.q_al q).
(* [comment removed for export] *)
Definition WEXIT (ps' : PML.pstate) (code : Z) (M' : mem) (eg' : eghost) : Prop :=
  let rr := PMW.rm_step PMR.the_rm PMW.FParseSome (ic0 I) (PMW.inp_win ps (iwinb I) (ix I)) in
  code = PMW.r_code rr /\ PMES.g_es eg' = PMW.es_run (PMES.g_es eg0) (PMW.r_evs rr) /\
  (exists pay, 0 <= pay <= PMW.r_allow rr /\ PMES.g_len eg' = PMES.g_len eg0 + PMW.ind_run (PMES.g_es eg0) (PMW.r_evs rr) + pay) /\
  (code = 0 -> PMW.rm_match PMR.the_rm (PMW.r_ctrl rr) M' P ps' /\ PMW.r_used rr = PML.winlen ps - PML.winlen ps' /\ PMW.win_bytes M' ps' (PMW.w_after PMR.the_rm rr (iwinb I))).

(* [comment removed for export] *)
Definition skip_cut (i : nat) : bool := match ret_src i with Some (_, _, pc) => Z.eqb pc PML.PC_SKIP_SPACE | None => false end.
(* [comment removed for export] *)
Definition pt_post (i : nat) (E1 : env) (M1 : mem) : Prop :=
  let nxg := (CC.cp_nx (cutn i) - APC.NCS - 5)%nat in let a0v := (CC.cp_nx (cutn i) - APC.NCS + 4)%nat in
  let jv := bv_unsigned (ev E1 53) in let rkv := bv_unsigned (ev E1 54) in      (* [comment removed for export] *)
  exists (ps2 : PML.pstate) (code : Z) (g' : PML.ls_state) (cw : option (Z * Z)),
    PML.parser_at M1 P (PML.ps_set_win ps2 cw) /\ PML.wf_ps ps2 /\ PML.win_ok M1 LBo ps2 /\ PML.buf_bound ps2 B /\ PML.ec_at M1 E code /\ (code <> 0 -> PML.ps_more ps2 = false) /\
    PML.ls_ok g' M1 /\ (g' = g \/ (g' = PML.LS2 /\ code <> 0)) /\ bv_unsigned (ev E1 nxg) = code /\
    CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps2 /\ (skip_cut i = true -> code = 0) /\
    (* [comment removed for export] *)
    (if PSM2.cur_cut i then exists p e, cw = Some (p, e) /\ PML.ps_win ps2 = Some (bv_unsigned (ev E1 a0v), e) /\ p <= bv_unsigned (ev E1 a0v) <= e else cw = PML.ps_win ps2) /\
    (code = 0 ->
       PML.ps_more ps2 = true /\ snd (PSA.wincells (PML.ps_win ps2)) = wend /\ seg <= fst (PSA.wincells (PML.ps_win ps2)) <= wend /\
       (under0 i = true -> In (PML.ps_st ps2) [PML.ST_ACCEPT; PML.ST_EXPECT_COMMA_OR_END]) /\
       (in_loop i = true ->
          if Z.eqb (reent_pc i) L2PC then PML.winlen ps2 = jv
          else PML.winlen ps2 + 1 <= jv \/ (PML.winlen ps2 = jv /\ RANK ps2 + 1 <= rkv)) /\
       xsync ps2 eg) /\
    PTW i ps2 code M1.      (* [comment removed for export] *)

(* [comment removed for export] *)
Definition eofc (ps1 : PML.pstate) : Prop := wlen = 0 -> PML.ps_more ps1 = true -> In st0 [PML.ST_NUMBER; PML.ST_CR] /\ ~ In (PML.ps_st ps1) [PML.ST_NUMBER; PML.ST_CR].

(* [comment removed for export] *)
Definition XDEP (i : nat) (E1 : env) : Prop :=
  match kind_of i with KPt => True | _ => match vw i with Some (pv, _, _) => PMES.depth (PMES.g_es eg) = uv E1 (PB4.pv_level pv) | None => True end end.
(* [comment removed for export] *)
Definition XI (i : nat) (E1 : env) (M1 : mem) : Prop :=
  (* [comment removed for export] *)
  L5.defined M1 (sp - CH.hd_scr G.HDECL) (CH.hd_scr G.HDECL) /\
  (* [comment removed for export] *)
  (i <> 0%nat -> st0 <> PML.ST_ACCEPT) /\ (in_loop i = true -> 1 <= wlen) /\ XDEP i E1 /\
  match kind_of i with
  | KPt => pt_post i E1 M1
  | k =>
      match vw i with
      | Some (pv, pe, ce) =>
          exists (bm bd : bool) (stack buf : list Z),
            contents pv pe ce E1 M1 bm bd stack buf /\
            match k with
            | KInv | KVis =>             (* [comment removed for export] *)
                let ps1 := ps_of pv pe ce E1 bm bd stack buf in
                PML.ls_ok g M1 /\
                PML.wf_ps ps1 /\ PML.buf_bound ps1 B /\ PML.ws_ok ps1 /\ ((i = I_HLO \/ i = I_HHI \/ i = I_HN \/ i = I_L \/ i = I_HS) -> RANK ps1 <= bv_unsigned (ev E1 54)) /\ (i = I_L0 -> eofc ps1)
            | KParent =>                 (* [comment removed for export] *)
                let ps1 := ps_of pv pe ce E1 bm bd stack buf in
                PML.ls_ok g M1 /\ PML.wf_ps ps1 /\ PML.buf_bound ps1 B
            | KVec =>                    (* [comment removed for export] *)
                PML.ls_ok g M1 /\
                match CAX.cell_at (CC.cp_know (cutn i)) (EVar 2) (-120) 1 with
                | Some (ELit x) => exists old, stack = old ++ [x] /\ let ps1 := ps_of pv pe ce E1 bm bd old buf in PML.wf_ps ps1 /\ PML.buf_bound ps1 B
                | _ => False
                end
            | KPop =>                    (* [comment removed for export] *)
                PML.ls_ok g M1 /\
                exists x, bv_unsigned (ev E1 (CC.cp_nx (cutn i) - APC.NCS - 1)) = x /\
                  let ps1 := ps_of pv pe ce E1 bm bd (stack ++ [x]) buf in PML.wf_ps ps1 /\ PML.buf_bound ps1 B /\ (in_loop i = true -> RANK ps1 <= bv_unsigned (ev E1 54)) /\ key_inv ps1      (* [comment removed for export] *)
            | KPushB =>                  (* [comment removed for export] *)
                PML.ls_ok g M1 /\
                buf = [uv E1 (pushed_of i)] /\ L5.bytes_at RSEGS M1 (uv E1 pe) buf /\
                  let ps1 := ps_of pv pe ce E1 bm bd stack [] in PML.wf_ps ps1 /\ PML.buf_bound ps1 B
            | KSetEc | KErr =>           (* [comment removed for export] *)
                let ps1 := ps_of pv pe ce E1 false bd stack buf in
                PML.ls_ok PML.LS2 M1 /\ PML.wf_ps ps1 /\ Z.of_nat (length buf) + PML.winlen ps1 <= B /\ B < 2 ^ 26 /\ (exists code, PML.ec_at M1 E code /\ 1 <= code <= 31 /\ WERR code) /\ (k = KErr -> bm = false)      (* [comment removed for export] *)
            | KPt => False
            end
      | None => False
      end
  end.

Lemma vw_total : forallb (fun i => match kind_of i with KPt => true | _ => match vw i with Some _ => true | None => false end end) (seq 0 (length G.CPS)) = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20!2+_[!2+_[+hW+e;+e;-a9RN$x;R!1+a90+9!1'hX#12$p;R0,;,Mvv!2,^4+9,;!3+:+9!3'hT+c8$i;R+c8-hURN$x;R+hU+9!1'hV#191111111,;1!2'hY,^<!2'_0+hZ'h[,;").
Qed.
