Definition ps_with (p : PML.pstate) (st : Z) (stack : list Z) : PML.pstate :=
  PML.PS st (PML.ps_sst p) (PML.ps_nst p) (PML.ps_more p) (PML.ps_done p) (PML.ps_level p) stack (PML.ps_sb p) (PML.ps_scap p) (PML.ps_bcap p) (PML.ps_bptr p) (PML.ps_buf p) (PML.ps_win p).
Definition MATCHV (c : PMR.ctrl) (pv : PB4.pvals2) (pe ce : expr) (E1 : env) (M1 : mem) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S20|30;!1+8+2$c;R+h\$pv;R+hW$pe;R+e;$ce;R+e;$E1;R+g[$M1;R%~R!1+`G!1,`H|600;!1+a9!1+`G!1,`H0!2+>+9$bm;R+9!2+>+9$bd;R+9!2+>1$stack;R1!2+>1$buf;R1!2+?!9'i0#9#8#7#6#5#4#3#2#1!2+?!3+_3+2$x;R+2!2+?!2'A,^O#1!2'A#1!1,B|77f;#2!2+?%~R!3+:+2!2'eZ#6!1'i1#9'^Y!4'a<'a7#6!2'eZ#7#9#2!4'hM#:#5!2'a1/SCFG_P;/I;!8'i2#9#8#7#6#4#3#2#1").
Definition MATCHP (c : PMR.ctrl) (pv : PB4.pvals2) (pe ce : expr) (E1 : env) (M1 : mem) (x : Z) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S20|30;!1+8+2$c;R+h\$pv;R+hW$pe;R+e;$ce;R+e;$E1;R+g[$M1;R%~R!1+`G!1,`H|600;!1+a9!1+`G!1,`H0$x;R+2!2+>+9$bm;R+9!2+>+9$bd;R+9!2+>1$stack;R1!2+>1$buf;R1!2+?!9'i0#:#9#8#7#6#4#3#2#1!2+?!3+_3+2$x;R+2!2+?!2'A,^O#1!2'A#1!1,B|77f;#2!2+?!1'Z!3+:+2#5'^Y!2+?!1'Z!3+:+2#5'_9!4'hM#;#6!2'a1/SCFG_P;/I;!3'i3!8'i2#:#9#8#7#4#3#2#1#5#2").
Definition MATCHK (c : PMR.ctrl) (pv : PB4.pvals2) (pe ce : expr) (E1 : env) (M1 : mem) (pushed : Z) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S20|30;!1+8+2$c;R+h\$pv;R+hW$pe;R+e;$ce;R+e;$E1;R+g[$M1;R%~R!1+`G!1,`H|600;!1+a9!1+`G!1,`H0$pushed;R+2!2+>+9$bm;R+9!2+>+9$bd;R+9!2+>1$stack;R1!2+>1$buf;R1!2+>1$old;R1!2+?!9'i0#;#:#9#8#7#5#4#3#2!2+?!3+_3+2$x;R+2!2+?!2'A,^O#1!2'A#1!1,B|77f;#3!2+?!3+:1#3!3'^0+2#1!3,5+2#6!1,^1+2!4'hM#<#7!2'a1/SCFG_P;/I;!3'i3!8'i2#;#:#9#8#5#4#3#2!2'eZ#8!1'i1#;#1").
(* [comment removed for export] *)
Definition TAGV (i : nat) : option nat := if Nat.eqb i I_ENTRY then Some 49%nat else if (Nat.eqb i I_L0 || Nat.eqb i I_HS)%bool then Some 69%nat else None.
Definition TAGR (i : nat) (c : PMR.ctrl) (E1 : env) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S00$i;R+c8$c;R+h\$E1;R+g[%v;R+c8%~R!3+:!1+a9+c8!1'i4#4!2,aA+c8#1%~R!3+:+2!1'hS#4'^Y!2'A!2'eZ#4!1,dG#3!1,B,C").
Definition SIM (i : nat) (E1 : env) (M1 : mem) : Prop :=
  match kind_of i with
  | KInv =>      (* [comment removed for export] *)
      match vw i with
      | Some (pv, pe, ce) =>
          if Nat.eqb i I_ENTRY then MATCHV c0 pv pe ce E1 M1 /\ PMRF.stack_ok c0 /\ SYNC [] 0 /\ TAGR I_ENTRY c0 E1
          else exists c evs al, PMRF.hreach c0 w0 c (rem E1 (PB4.pv_wptr pv) (PSCW.OFF i)) evs al /\ MATCHV c pv pe ce E1 M1 /\ SYNC evs al /\
                 (i = I_L2 -> PMR.c_st c <> PML.ST_STRING /\ PMR.c_st c <> PML.ST_NUMBER) /\      (* [comment removed for export] *)
                 (i = I_HLO -> PMR.c_st c <> PML.ST_STRING) /\     (* [comment removed for export] *)
                 TAGR i c E1                                          (* [comment removed for export] *)
      | None => False
      end
  | KVis =>      (* [comment removed for export] *)
      match vw i with
      | Some (pv, pe, ce) => exists c b r evs al, PMRF.hreach c0 w0 c (b :: r) evs al /\ r = rem E1 (PB4.pv_wptr pv) (PSCW.OFF i) /\ PMR.c_more c = true /\
                             PMR.dispatch (PMR.c_st c) (PMR.top c) b = PMR.ALitDone /\ MATCHV c pv pe ce E1 M1 /\ SYNC (evs ++ [PMW.EkLit]) (al + PMR.AL_LIT)
      | None => False
      end
  | KVec =>      (* [comment removed for export] *)
      match vw i with
      | Some (pv, pe, ce) => exists c b r evs al, PMRF.hreach c0 w0 c (b :: r) evs al /\ r = rem E1 (PB4.pv_wptr pv) (PSCW.OFF i) /\ PMR.c_more c = true /\
                             Some (PMR.dispatch (PMR.c_st c) (PMR.top c) b) = PSCW.ract i /\
                             MATCHK c pv pe ce E1 M1 (match PSCW.ract i with Some (PMR.AString true) => PML.ST_MEMBER_NAME | _ => PMR.c_st c end) /\ SYNC evs al
      | None => False
      end
  | KPushB =>    (* [comment removed for export] *)
      match vw i with
      | Some (pv, pe, ce) => exists c b r evs al, PMRF.hreach c0 w0 c (b :: r) evs al /\ r = rem E1 (PB4.pv_wptr pv) (PSCW.OFF i) /\ PMR.c_more c = true /\
                             PMR.dispatch (PMR.c_st c) (PMR.top c) b = PMR.ANumber /\ uv E1 (pushed_of i) = b /\ MATCHV c pv pe ce E1 M1 /\ SYNC evs al
      | None => False
      end
  | KPop =>      (* [comment removed for export] *)
      match vw i with
      | Some (pv, pe, ce) => exists c evs al, PMRF.hreach c0 w0 c (rem E1 (PB4.pv_wptr pv) (PSCW.OFF i)) evs al /\
                             MATCHP c pv pe ce E1 M1 (bv_unsigned (ev E1 (CC.cp_nx (cutn i) - APC.NCS - 1)%nat)) /\ SYNC evs al
      | None => False
      end
  | KParent =>   (* [comment removed for export] *)
      match vw i with
      | Some (pv, pe, ce) =>
      exists c b r evs al, PMRF.hreach c0 w0 c (b :: r) evs al /\ PMR.c_more c = true /\ SYNC evs al /\ uv E1 (PSCW.A0 i) = PMR.top c /\ MATCHV c pv pe ce E1 M1 /\
        match PSCW.PPAR i with
        | Some (st, b0, snd) => (forall p, PMR.dispatch (PMR.c_st c) p b = PMR.dispatch st p b0) /\ (snd = true -> (PMR.top c =? PML.ST_ARRAY) = false)
        | None => False
        end
      | None => False
      end
  | KErr | KSetEc => True      (* [comment removed for export] *)
  | KPt => True           (* [comment removed for export] *)
  end.
(* [comment removed for export] *)
Lemma SIM_inv : forall i pv pe ce E1 M1, kind_of i = KInv -> i <> I_ENTRY -> vw i = Some (pv, pe, ce) ->
